{
  "evidence": [
    {
      "ref_id": "p064",
      "group_ids": [
        "E3"
      ],
      "quote": "违反本制度规定收受或对外提供礼品、餐饮或商业款待或其他利益 的,视情节严重程度,给予相应的纪律处分,直至开除;",
      "kind": "policy",
      "period": "未明确",
      "scope": "药明生物技术有限公司员工",
      "relevance": "披露了因违反反腐败制度（如违规接受宴请）导致的最严厉后果为“开除”，属于裁员/解雇相关的纪律处分制度安排。"
    },
    {
      "ref_id": "p065",
      "group_ids": [
        "E3"
      ],
      "quote": "Employees who accept or give gifts or provide benefits (gift, meal or business hospitality, or other interest) against this policy, corresponsive disciplinary actions (up to dismissal) shall be given depending on the severity of the violation;",
      "kind": "policy",
      "period": "未明确",
      "scope": "WuXi Biologics employees",
      "relevance": "英文原文确认了针对违规行为的纪律处分最高可达“dismissal”（解雇），支持裁员/解雇程序中的处罚依据。"
    },
    {
      "ref_id": "p066",
      "group_ids": [
        "E3"
      ],
      "quote": "对于侵占本公司资产、利用本公司资产谋利或用于私人用途等行为, 视情节严重程度,给予留司察看至解除劳动合同或被退回劳务派遣 机构;",
      "kind": "policy",
      "period": "未明确",
      "scope": "药明生物技术有限公司员工及劳务派遣人员",
      "relevance": "明确提及“解除劳动合同”作为对严重违纪行为（如侵占资产）的处理措施，直接关联裁员/解雇制度。"
    },
    {
      "ref_id": "p067",
      "group_ids": [
        "E3"
      ],
      "quote": "Employees who have committed embezzlement of the Company's assets, gained profits by taking advantage of the Company's assets or used them for personal ends, etc., disciplinary actions will be taken up to including retain post on probation, dismissal or sent back to the employment agency depending on the severity of the violation upon discovery;",
      "kind": "policy",
      "period": "未明确",
      "scope": "WuXi Biologics employees and dispatched workers",
      "relevance": "英文原文确认了包括“dismissal”（解雇）和“sent back to the employment agency”（退回派遣机构）在内的处理措施，涉及劳动关系解除的程序性规定。"
    }
  ]
}
